// Generated from src/registry/sources/control-ui/recipes/breadcrumb.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const breadcrumbKnobs = ["--cui-breadcrumb-list-foreground", "--cui-breadcrumb-page-foreground"] as const;
export type BreadcrumbKnobStyle = Partial<Record<(typeof breadcrumbKnobs)[number], string>>;

@layer components {
  :where([data-control-family="breadcrumb"][data-slot="root"]) {
    --cui-breadcrumb-list-foreground: var(--muted-foreground);
    --cui-breadcrumb-page-foreground: var(--foreground);
  }

  :where([data-control-family="breadcrumb"][data-slot="page"]) {
    font-weight: var(--font-weight-normal);
    color: var(--cui-breadcrumb-page-foreground);
  }

  :where([data-control-family="breadcrumb"][data-slot="list"]) {
    gap: calc(var(--spacing) * 1.5);
    font-size: var(--text-sm);
    line-height: var(--text-sm--line-height);
    color: var(--cui-breadcrumb-list-foreground);
  }

  @media (width >= 40rem) {
    :where([data-control-family="breadcrumb"][data-slot="list"]) {
      gap: calc(var(--spacing) * 2.5);
    }
  }

  :where([data-control-family="breadcrumb"][data-slot="item"]) {
    gap: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="breadcrumb"][data-slot="ellipsis"]) {
    inline-size: calc(var(--spacing) * 9);
    block-size: calc(var(--spacing) * 9);
  }
}

@property --cui-breadcrumb-list-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-breadcrumb-page-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { useRender } from "@base-ui/react/use-render";
import { ChevronRight, MoreHorizontal } from "lucide-react";
import type { ComponentProps, CSSProperties } from "react";
import type { RenderProp } from "@/components/control-ui/control-props";
import type { BreadcrumbKnobStyle } from "@/components/control-ui/knob-contracts/breadcrumb-knobs";
import { cn } from "@/components/control-ui/lib/cn";

export function Breadcrumb({ className, ...props }: ComponentProps<"nav"> & { style?: CSSProperties & BreadcrumbKnobStyle }) {
  return (
    <nav
      aria-label="breadcrumb"
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="root"
      className={className}
      {...props}
    />
  );
}

export function BreadcrumbList({
  className,
  ...props
}: Omit<ComponentProps<"ol">, "style"> & { style?: CSSProperties & BreadcrumbKnobStyle }) {
  return (
    <ol
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="list"
      className={cn("flex flex-wrap items-center break-words", className)}
      {...props}
    />
  );
}

export function BreadcrumbItem({ className, ...props }: ComponentProps<"li"> & { style?: CSSProperties & BreadcrumbKnobStyle }) {
  return (
    <li
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="item"
      className={cn("inline-flex items-center", className)}
      {...props}
    />
  );
}

export function BreadcrumbLink({
  render,
  className,
  children,
  ...props
}: ComponentProps<"a"> & {
  render?: RenderProp<ComponentProps<"a">>;
}) {
  return useRender({
    defaultTagName: "a",
    render,
    props: {
      ...props,
      "data-control-ui": "breadcrumb",
      "data-control-family": "breadcrumb",
      "data-slot": "link",
      className: className,
      children,
    },
  });
}

export function BreadcrumbPage({
  className,
  ...props
}: Omit<ComponentProps<"span">, "style"> & { style?: CSSProperties & BreadcrumbKnobStyle }) {
  return (
    <span
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="page"
      aria-current="page"
      className={className}
      {...props}
    />
  );
}

export function BreadcrumbSeparator({
  children,
  className,
  ...props
}: ComponentProps<"li"> & { style?: CSSProperties & BreadcrumbKnobStyle }) {
  return (
    <li
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="separator"
      role="presentation"
      aria-hidden="true"
      className={cn("[&>svg]:size-3.5", className)}
      {...props}
    >
      {children ?? <ChevronRight />}
    </li>
  );
}

export function BreadcrumbEllipsis({ className, ...props }: ComponentProps<"span"> & { style?: CSSProperties & BreadcrumbKnobStyle }) {
  return (
    <span
      data-control-ui="breadcrumb"
      data-control-family="breadcrumb"
      data-slot="ellipsis"
      role="presentation"
      aria-hidden="true"
      className={cn("flex items-center justify-center", className)}
      {...props}
    >
      <MoreHorizontal className="size-4" />
      <span className="sr-only">More</span>
    </span>
  );
}
